#' Correlation Matrix (Python Core)
#'
#' 
#' @param data .
#' @param dep .
#' @param typestatistics .
#' @param partial .
#' @param naHandling .
#' @param padjustmethod .
#' @param conflevel .
#' @param interactive .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$correlations} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$matrix} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$correlations$asDF}
#'
#' \code{as.data.frame(results$correlations)}
#'
#' @export
pyjjcorrmat <- function(
    data,
    dep = NULL,
    typestatistics = "parametric",
    partial = FALSE,
    naHandling = "listwise",
    padjustmethod = "holm",
    conflevel = 0.95,
    interactive = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyjjcorrmat requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL))


    options <- pyjjcorrmatOptions$new(
        dep = dep,
        typestatistics = typestatistics,
        partial = partial,
        naHandling = naHandling,
        padjustmethod = padjustmethod,
        conflevel = conflevel,
        interactive = interactive,
        showConsole = showConsole)

    analysis <- pyjjcorrmatClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

